package com.example.discussions;import com.example.discussions.model.Vote;import jakarta.persistence.Table;import org.junit.jupiter.api.Test;import java.util.Arrays;import static org.junit.jupiter.api.Assertions.*;class VoteConstraintTest{@Test void voteHasDatabaseLevelUserDiscussionUniqueness(){var table=Vote.class.getAnnotation(Table.class);assertTrue(Arrays.stream(table.uniqueConstraints()).anyMatch(c->Arrays.equals(c.columnNames(),new String[]{"user_id","discussion_id"})));}}
